"""Assemble the pinned Phonopy Cu-QHA reference with Python's standard library.

Without flags this rebuilds the two JSON files from local originals. Use
--fetch to obtain missing originals from the fixed upstream revision, or
--check to check the original and generated bytes without writing anything.
"""

import argparse
from concurrent.futures import ThreadPoolExecutor
from decimal import Decimal
import hashlib
import json
import lzma
from pathlib import Path
import re
from urllib.request import urlopen


ROOT = Path(__file__).resolve().parents[1]
EXAMPLES = ROOT / 'dist/data/examples'
EXAMPLE = EXAMPLES / 'phonopy-cu-qha'
REPOSITORY = 'https://github.com/phonopy/phonopy'
COMMIT = '18cad919af8fe8aad349e04f101887fa19b051a0'
UPSTREAM_DIRECTORY = 'test/cui/phonopy_qha/Cu-QHA'
UPSTREAM_TEST = 'test/cui/phonopy_qha/test_phonopy_qha_script.py'
THERMAL_GIT_BLOBS = (
    'c2489619f0c3a9e52a63a4d02bc73b51a1fe9d10',
    '74677de41d5c99938c648c22bd8a6aa42d6da997',
    '62df3146d935f356ac5e2d8dfc0ae533f3e6c38f',
    '45f19c246aa9ea279ef79c20c209e0ad754c7269',
    '7d209038c1df17392181bd32b5e31a79bd0c1f23',
    '3518fc3ad5bdc29d75338a0496723979fb37bc32',
    '0cca4d4a61a02cbbd6aa94adbedfba81baf61609',
    'e2dc723691bec3de8c91a7e9935a6f0bfa8cb93b',
    '512802dd283d4245e39c86d4b4097ae2ab678ddc',
    '352b2201f799487497cfed0c40b4e003bebbbfb3',
    '1d00e695ed0a47298047adb845afe545d35b36f7',
)
TEMPERATURES = list(range(0, 2501, 10))
NATOM = 4
MODE_COUNT = 96000
# Thermal YAML rounds to ten decimal places in Å³; e-v.dat prints more places.
VOLUME_PAIR_TOLERANCE = Decimal('0.00000000005')


def require(condition, message):
    if not condition:
        raise ValueError(message)


def original_inputs():
    records = [
        ('e-v.dat', f'{UPSTREAM_DIRECTORY}/e-v.dat', '396e5eff37652220f86756a42fcfb4e3b3763a50', None),
        ('LICENSE.txt', 'LICENSE', 'ad98c46d8bef0cac32974e405865147cc80679ff', 'phonopy-cu-LICENSE.txt'),
    ]
    for index, sha in enumerate(THERMAL_GIT_BLOBS):
        name = f'thermal_properties.yaml-{index:02d}.xz'
        reuse = 'phonopy-cu-thermal-index05.yaml.xz' if index == 5 else None
        records.append((name, f'{UPSTREAM_DIRECTORY}/{name}', sha, reuse))
    return records


def blob_sha(data):
    return hashlib.sha1(f'blob {len(data)}\0'.encode('ascii') + data).hexdigest()


def checksum(data):
    return {'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest()}


def fetch_inputs():
    """Verify every blob before publishing any of the fetched source files."""
    def one(record):
        name, path, sha, reuse = record
        target = EXAMPLE / name
        if target.is_file():
            data = target.read_bytes()
        elif reuse and (EXAMPLES / reuse).is_file():
            data = (EXAMPLES / reuse).read_bytes()
        else:
            url = f'https://raw.githubusercontent.com/phonopy/phonopy/{COMMIT}/{path}'
            with urlopen(url, timeout=30) as source:
                data = source.read(100_001)
            require(len(data) <= 100_000, f'Unexpected source size: {name}')
        require(blob_sha(data) == sha, f'Pinned upstream Git blob mismatch: {name}')
        return name, data

    with ThreadPoolExecutor(max_workers=6) as pool:
        verified = list(pool.map(one, original_inputs()))
    EXAMPLE.mkdir(parents=True, exist_ok=True)
    for name, data in verified:
        target = EXAMPLE / name
        if not target.exists():
            target.write_bytes(data)


def read_inputs():
    originals, provenance = {}, {}
    for name, path, expected_sha, reuse in original_inputs():
        data = (EXAMPLE / name).read_bytes()
        require(blob_sha(data) == expected_sha, f'Pinned upstream Git blob mismatch: {name}')
        if reuse:
            require(data == (EXAMPLES / reuse).read_bytes(), f'Existing Cu source bytes differ: {reuse}')
        originals[name] = data
        provenance[name] = {'path': name, 'sourcePath': path, 'gitBlobSha1': expected_sha,
                            'url': f'{REPOSITORY}/blob/{COMMIT}/{path}', **checksum(data)}
    return originals, provenance


def energy_volume_rows(data):
    rows = [tuple(Decimal(field) for field in line.split()) for line in data.decode('ascii').splitlines()
            if line.strip() and not line.lstrip().startswith('#')]
    require(len(rows) == len(THERMAL_GIT_BLOBS) and all(len(row) == 2 for row in rows),
            'Static input must contain one volume and one energy for each pinned record')
    require(all(volume.is_finite() and volume > 0 and energy.is_finite() for volume, energy in rows),
            'Volumes and static energies must be finite, with positive volumes')
    require(all(a[0] < b[0] for a, b in zip(rows, rows[1:])), 'Original static volumes must increase strictly')
    return rows


def verify_thermal_header(text, expected_volume, name):
    # A dependency-free source audit over fixed, Git-hash-verified files. The
    # regression test independently parses each entire document with PyYAML.
    header, separator, table = text.partition('\nthermal_properties:\n')
    require(bool(separator), f'Thermal properties table missing: {name}')

    def field(key):
        matches = re.findall(rf'^{key}:[ \t]+([^\s]+)[ \t]*$', header, re.MULTILINE)
        require(len(matches) == 1, f'Expected exactly one {key} field: {name}')
        return matches[0]

    require(int(field('natom')) == NATOM, f'Input must have four atoms per calculation cell: {name}')
    require(int(field('num_modes')) == MODE_COUNT and int(field('num_integrated_modes')) == MODE_COUNT,
            f'Expected common complete mode counts: {name}')
    units = dict(re.findall(r'^  (temperature|free_energy|entropy|heat_capacity):[ \t]+(\S+)[ \t]*$',
                            header, re.MULTILINE))
    require(units == {'temperature': 'K', 'free_energy': 'kJ/mol', 'entropy': 'J/K/mol', 'heat_capacity': 'J/K/mol'},
            f'Unexpected thermal-property units: {name}')
    require(not re.search(r'^(band_index|exclude_gamma_acoustic|cutoff_frequency):', header, re.MULTILINE),
            f'The baseline must use the unmodified full mode table: {name}')
    temperature_rows = [Decimal(value) for value in re.findall(r'^- temperature:[ \t]+(\S+)[ \t]*$', table, re.MULTILINE)]
    require(temperature_rows == TEMPERATURES, f'Temperature records differ from the common grid: {name}')
    thermal_volume = Decimal(field('volume'))
    require(thermal_volume.is_finite() and abs(thermal_volume - expected_volume) <= VOLUME_PAIR_TOLERANCE,
            f'Printed thermal volume does not pair with its static energy: {name}')
    return thermal_volume


def as_json(document, *, formatted=False):
    if formatted:
        body = json.dumps(document, ensure_ascii=True, allow_nan=False, indent=2)
    else:
        body = json.dumps(document, ensure_ascii=True, allow_nan=False, separators=(',', ':'))
    return (body + '\n').encode('ascii')


def documents(originals, records):
    data = {'cellBasis': 'same-input-cell', 'natom': NATOM,
            'units': {'volume': 'angstrom^3', 'staticEnergy': 'eV/input-cell', 'temperature': 'K'},
            'volumes': [], 'staticEnergies': [], 'thermalFiles': []}
    thermal_files = []
    for index, (volume, energy) in enumerate(energy_volume_rows(originals['e-v.dat'])):
        name = f'thermal_properties.yaml-{index:02d}.xz'
        yaml_bytes = lzma.decompress(originals[name])
        text = yaml_bytes.decode('utf-8')
        printed_volume = verify_thermal_header(text, volume, name)
        if index == 5:
            require(yaml_bytes == (EXAMPLES / 'phonopy-cu-thermal-index05.yaml').read_bytes(),
                    'Decoded index 05 differs from the existing fixed-volume Cu source')
        data['volumes'].append(float(volume))
        data['staticEnergies'].append(float(energy))
        data['thermalFiles'].append(text)
        thermal_files.append({'index': index, **records[name], 'yaml': checksum(yaml_bytes),
                              'staticVolumeAngstrom3': float(volume), 'printedThermalVolumeAngstrom3': float(printed_volume),
                              'staticEnergyEVPerInputCell': float(energy)})
    payload = as_json(data)
    upstream_test = f'{REPOSITORY}/blob/{COMMIT}/{UPSTREAM_TEST}'
    source = {
        'format': 'symmetry-lab-phonopy-cu-qha-source-1', 'id': 'phonopy-cu-qha', 'title': 'Official Phonopy Cu-QHA input files',
        'repository': REPOSITORY, 'commit': COMMIT, 'upstreamDirectory': UPSTREAM_DIRECTORY,
        'upstreamUrl': f'{REPOSITORY}/tree/{COMMIT}/{UPSTREAM_DIRECTORY}', 'upstreamTest': upstream_test,
        'license': 'BSD-3-Clause', 'licenseFile': records['LICENSE.txt'], 'eVFile': records['e-v.dat'],
        'volumeCount': len(thermal_files), 'natom': NATOM, 'cellBasis': 'same-input-cell',
        'temperatureCount': len(TEMPERATURES), 'temperatureMinK': TEMPERATURES[0],
        'temperatureMaxK': TEMPERATURES[-1], 'temperatureStepK': TEMPERATURES[1] - TEMPERATURES[0],
        'numModes': MODE_COUNT, 'numIntegratedModes': MODE_COUNT,
        'pairingToleranceAngstrom3': float(VOLUME_PAIR_TOLERANCE), 'thermalFiles': thermal_files,
        'payload': {'path': 'payload.json', **checksum(payload)},
        'representation': 'Original XZ files and static table, with losslessly decoded YAML UTF-8 strings in payload.json.',
        'rebuild': 'python scripts/build-cu-qha-source.py',
    }
    return {'payload.json': payload, 'source.json': as_json(source, formatted=True)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument('--fetch', action='store_true')
    mode.add_argument('--check', action='store_true')
    args = parser.parse_args()
    if args.fetch:
        fetch_inputs()
    generated = documents(*read_inputs())
    for name, data in generated.items():
        path = EXAMPLE / name
        if args.check:
            require(path.is_file() and path.read_bytes() == data, f'Generated Cu-QHA file is stale: {name}')
        else:
            path.write_bytes(data)
    print(f'Cu-QHA source: {len(THERMAL_GIT_BLOBS)} verified volume pairs, {len(TEMPERATURES)} temperatures; '
          f'payload {checksum(generated["payload.json"])}.')


if __name__ == '__main__':
    main()
